#include <stdio.h>
#include <stdlib.h>

static long long T[100005];
static long long heap_w[100005];
static int heap_f[100005];

int cmp_desc(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return 1;
    if (x > y) return -1;
    return 0;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int i = 0; i < N; ++i) {
        scanf("%lld", &T[i]);
    }

    qsort(T, N, sizeof(long long), cmp_desc);

    for (int i = 0; i < M; ++i) {
        int f;
        scanf("%d", &f);
        heap_w[i] = 0;
        heap_f[i] = f;
    }

    long long ans = 0;

    for (int i = 0; i < N; ++i) {
        long long w = heap_w[0];
        int f = heap_f[0];

        ans += w * T[i];

        heap_w[0] = w + f;

        int idx = 0;
        while (1) {
            int c = idx * 2 + 1;
            if (c >= M) break;

            if (c + 1 < M && heap_w[c + 1] < heap_w[c]) {
                ++c;
            }

            if (heap_w[idx] <= heap_w[c]) break;

            long long tw = heap_w[idx];
            heap_w[idx] = heap_w[c];
            heap_w[c] = tw;

            int tf = heap_f[idx];
            heap_f[idx] = heap_f[c];
            heap_f[c] = tf;

            idx = c;
        }
    }

    printf("%lld\n", ans);
    return 0;
}
